const fs = require('fs');
const results = JSON.parse(fs.readFileSync('lint-results.json', 'utf8'));
const summary = {};
results.forEach(file => {
    file.messages.forEach(msg => {
        const ruleId = msg.ruleId || 'unknown';
        summary[ruleId] = (summary[ruleId] || 0) + 1;
    });
});
console.log(JSON.stringify(summary, null, 2));

import { NextRequest, NextResponse } from 'next/server';
import { supabase } from '../../../../lib/supabase';
import { processDocument } from '../../../../lib/document-processing';
import { generateEmbeddings } from '../../../../lib/embeddings';
import { generateDocumentId, generateChunkId } from '../../../../lib/utils/id-generator';
// @ts-ignore
import PDFParser from 'pdf2json';
import type { PostgrestError } from '@supabase/supabase-js';

export const maxDuration = 60;

export async function POST(req: NextRequest) {
    try {
        const formData = await req.formData();
        const file = formData.get('file') as File | null;
        const source = formData.get('source') as string || 'Upload';

        if (!file) {
            return NextResponse.json(
                { error: 'No file provided' },
                { status: 400 }
            );
        }

        let content = '';
        const fileType = file.type;
        const fileName = file.name;



        // Extract text based on file type
        if (fileType === 'application/pdf') {
            const arrayBuffer = await file.arrayBuffer();
            const buffer = Buffer.from(arrayBuffer);

            content = await new Promise((resolve, reject) => {
                const pdfParser = new PDFParser(null, true);

                pdfParser.on("pdfParser_dataError", (errData: any) => {
                    reject(new Error(errData.parserError));
                });

                pdfParser.on("pdfParser_dataReady", (pdfData: any) => {
                    // getRawTextContent() returns text. 
                    // Often it's better to just use the raw text if available.
                    resolve(pdfParser.getRawTextContent());
                });

                pdfParser.parseBuffer(buffer);
            });
        } else if (
            fileType === 'application/json' ||
            fileName.endsWith('.json')
        ) {
            const text = await file.text();
            content = text;
            // Optional: You could parse it to validate or format it, 
            // but storing raw JSON text is often fine for RAG if it's readable.
        } else if (
            fileType.startsWith('text/') ||
            fileName.endsWith('.md') ||
            fileName.endsWith('.txt')
        ) {
            content = await file.text();
        } else {
            return NextResponse.json(
                { error: 'Unsupported file type. Please upload PDF, JSON, or Text files.' },
                { status: 400 }
            );
        }

        if (!content.trim()) {
            return NextResponse.json(
                { error: 'File appears to be empty or text could not be extracted.' },
                { status: 400 }
            );
        }

        // Process the document
        const processed = await processDocument(fileName, content, source);
        const documentId = generateDocumentId();

        // Save metadata
        const { error: docError } = await supabase.from('documents').insert({
            id: documentId,
            title: processed.title,
            source: processed.source,
            content: processed.content,
            metadata: {
                ...processed.metadata,
                fileType,
                originalName: fileName
            },
        });

        if (docError) throw new Error(`Failed to save document: ${docError.message}`);

        // Generate embeddings
        const embeddings = await generateEmbeddings(processed.chunks);

        // Save chunks
        const chunkRecords = processed.chunks.map((chunk, index) => ({
            id: generateChunkId(documentId, index),
            document_id: documentId,
            content: chunk,
            embedding: embeddings[index],
            metadata: {
                chunkIndex: index,
                totalChunks: processed.chunks.length,
                source: processed.source,
            },
        }));

        const { error: chunksError } = await supabase
            .from('document_chunks')
            .insert(chunkRecords);

        if (chunksError) {
            // Rollback
            await supabase.from('documents').delete().eq('id', documentId);
            throw new Error(`Failed to save chunks: ${chunksError.message}`);
        }

        return NextResponse.json({
            success: true,
            documentId,
            chunksCount: processed.chunks.length,
            message: `Successfully indexed ${fileName}`,
        });

    } catch (error) {
        console.error('Error in file upload:', error);
        return NextResponse.json(
            {
                error: 'Internal server error',
                details: error instanceof Error ? error.message : String(error),
            },
            { status: 500 }
        );
    }
}

import { NextRequest, NextResponse } from 'next/server';
import { supabase } from '../../../lib/supabase';

export async function GET(req: NextRequest) {
    try {
        // Check if tables exist by querying them
        const { data: documents, error: docError } = await supabase
            .from('documents')
            .select('count');

        const { data: chunks, error: chunkError } = await supabase
            .from('document_chunks')
            .select('count');

        if (docError || chunkError) {
            return NextResponse.json({
                status: 'error',
                message: 'Database tables not found or not accessible',
                errors: {
                    documents: docError?.message,
                    chunks: chunkError?.message,
                },
            });
        }

        return NextResponse.json({
            status: 'ok',
            message: 'RAG system is ready',
            tables: {
                documents: 'accessible',
                document_chunks: 'accessible',
            },
        });
    } catch (error) {
        return NextResponse.json({
            status: 'error',
            message: 'Health check failed',
            details: error instanceof Error ? error.message : String(error),
        });
    }
}

'use client';

import { ReactNode } from 'react';
import { cn } from '@/lib/utils';

interface AppLayoutProps {
    children: ReactNode;
    sidebar: ReactNode;
    toolWatch: ReactNode;
}

export default function AppLayout({ children, sidebar, toolWatch }: AppLayoutProps) {
    return (
        <div className="h-screen w-screen overflow-hidden bg-background flex">
            {/* Left Sidebar */}
            <aside className="w-60 h-full border-r border-sidebar-border bg-sidebar flex-shrink-0 hidden md:flex flex-col">
                {sidebar}
            </aside>

            {/* Main Content Area */}
            <main className="flex-1 h-full overflow-hidden flex flex-col">
                {children}
            </main>

            {/* Right Tool Watch Panel */}
            <aside className="w-80 h-full border-l border-sidebar-border bg-sidebar flex-shrink-0 hidden lg:flex flex-col">
                {toolWatch}
            </aside>
        </div>
    );
}

'use client';

import { useState, useRef, useEffect } from 'react';
import { Send, Bot, User, RefreshCw, Wrench, Lightbulb, Bug, Paperclip, X, Mic, FileText, Loader2, Image as ImageIcon } from 'lucide-react';
import { cn } from '../../lib/utils';
import QuickActionCard from './quick-action-card';
import MarkdownMessage from './markdown-message';
import { toast } from 'sonner';

interface Message {
    id: string;
    role: 'user' | 'assistant';
    content: string;
    image?: string | null;
}

interface SelectedFile {
    name: string;
    content: string;
    type: string;
    addToKB: boolean;
}

interface ChatProps {
    chatId?: string | null;
    projectName?: string;
    onChatCreated?: (id: string) => void;
}

export default function Chat({ chatId, projectName, onChatCreated }: ChatProps) {
    const [messages, setMessages] = useState<Message[]>([]);
    const [input, setInput] = useState('');
    const [status, setStatus] = useState<'ready' | 'streaming' | 'loading'>('loading');
    const [selectedImage, setSelectedImage] = useState<string | null>(null);
    const [selectedFile, setSelectedFile] = useState<SelectedFile | null>(null);

    // State for file upload operations
    const [isUploading, setIsUploading] = useState(false);

    const [isRecording, setIsRecording] = useState(false);
    const [isTranscribing, setIsTranscribing] = useState(false);
    const mediaRecorderRef = useRef<MediaRecorder | null>(null);
    const chunksRef = useRef<Blob[]>([]);

    const abortControllerRef = useRef<AbortController | null>(null);
    const messagesEndRef = useRef<HTMLDivElement>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);
    const imageInputRef = useRef<HTMLInputElement>(null);

    // Load chat history based on chatId prop
    useEffect(() => {
        async function loadHistory() {
            // If new chat with projectName, start fresh
            if (!chatId && projectName) {
                setMessages([]);
                setStatus('ready');
                return;
            }

            // If no chatId, load default history
            const url = chatId
                ? `/api/chat/history?chatId=${chatId}`
                : '/api/chat/history';

            try {
                const response = await fetch(url);
                if (response.ok) {
                    const data = await response.json();
                    setMessages(data.messages || []);
                } else {
                    setMessages([]);
                }
            } catch (error) {
                console.error('Error loading chat history:', error);
                setMessages([]);
            } finally {
                setStatus('ready');
            }
        }
        loadHistory();
    }, [chatId, projectName]);

    // Auto-scroll to bottom when messages change
    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [messages]);

    // Handle File Upload (Documents -> Preview, Images -> Vision)
    const handleFileUpload = async (file: File) => {
        if (file.type.startsWith('image/')) {
            const reader = new FileReader();
            reader.onloadend = () => {
                setSelectedImage(reader.result as string);
            };
            reader.readAsDataURL(file);
        } else {
            // Read file content for preview (Gemini-style)
            const reader = new FileReader();
            reader.onloadend = () => {
                const content = reader.result as string;
                setSelectedFile({
                    name: file.name,
                    content: content,
                    type: file.type || 'text/plain',
                    addToKB: false // Default to not adding to KB
                });
            };
            reader.onerror = () => {
                toast.error('Failed to read file');
            };
            reader.readAsText(file);
        }
    };

    const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            handleFileUpload(file);
        }
        // Reset input
        if (fileInputRef.current) fileInputRef.current.value = '';
        if (imageInputRef.current) imageInputRef.current.value = '';
    };

    const handlePaste = (e: React.ClipboardEvent) => {
        const items = e.clipboardData.items;
        for (const item of items) {
            if (item.kind === 'file') {
                const file = item.getAsFile();
                if (file) {
                    handleFileUpload(file);
                    e.preventDefault(); // Prevent default paste behavior for files
                }
            }
        }
    };

    const startRecording = async () => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            const mediaRecorder = new MediaRecorder(stream);
            mediaRecorderRef.current = mediaRecorder;
            chunksRef.current = [];

            mediaRecorder.ondataavailable = (e) => {
                if (e.data.size > 0) {
                    chunksRef.current.push(e.data);
                }
            };

            mediaRecorder.onstop = async () => {
                const audioBlob = new Blob(chunksRef.current, { type: 'audio/webm' });
                await handleTranscribe(audioBlob);
                stream.getTracks().forEach(track => track.stop());
            };

            mediaRecorder.start();
            setIsRecording(true);
        } catch (error) {
            console.error('Error accessing microphone:', error);
            alert('Could not access microphone. Please ensure you have granted permission.');
        }
    };

    const stopRecording = () => {
        if (mediaRecorderRef.current && isRecording) {
            mediaRecorderRef.current.stop();
            setIsRecording(false);
        }
    };

    const handleTranscribe = async (audioBlob: Blob) => {
        setIsTranscribing(true);
        try {
            const formData = new FormData();
            formData.append('file', audioBlob, 'recording.webm');

            const response = await fetch('/api/audio/transcribe', {
                method: 'POST',
                body: formData,
            });

            if (!response.ok) {
                throw new Error('Transcription failed');
            }

            const data = await response.json();
            if (data.text) {
                setInput((prev) => prev + (prev ? ' ' : '') + data.text);
            }
        } catch (error) {
            console.error('Error transcribing audio:', error);
        } finally {
            setIsTranscribing(false);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if ((!input.trim() && !selectedImage && !selectedFile) || status === 'streaming' || status === 'loading' || isTranscribing || isUploading) return;

        // Build message content with file context if present
        let messageContent = input;
        if (selectedFile) {
            // Limit file content to prevent context overflow (max 5000 chars)
            const maxContentLength = 5000;
            let fileContent = selectedFile.content;
            let truncatedNote = '';
            if (fileContent.length > maxContentLength) {
                fileContent = fileContent.slice(0, maxContentLength);
                truncatedNote = `\n\n[Note: File content truncated to ${maxContentLength} characters. Full file has ${selectedFile.content.length} characters.]`;
            }
            messageContent = `[File: ${selectedFile.name}]\n\n${fileContent}${truncatedNote}\n\n---\n\n${input}`;

            // If KB checkbox is checked, index the file in background
            if (selectedFile.addToKB) {
                const formData = new FormData();
                const blob = new Blob([selectedFile.content], { type: selectedFile.type });
                formData.append('file', blob, selectedFile.name);
                formData.append('source', 'User Upload');

                fetch('/api/documents/upload-file', { method: 'POST', body: formData })
                    .then(res => res.ok ? toast.success(`Added ${selectedFile.name} to Knowledge Base`) : toast.error('Failed to add to KB'))
                    .catch(() => toast.error('Failed to add to KB'));
            }
        }

        const userMessage: Message = {
            id: crypto.randomUUID(),
            role: 'user',
            content: messageContent,
            image: selectedImage
        };

        setMessages((prev) => [...prev, userMessage]);
        setInput('');
        setSelectedImage(null);
        setSelectedFile(null);
        setStatus('streaming');

        const abortController = new AbortController();
        abortControllerRef.current = abortController;

        try {
            // For new projects, include the project name
            const isNewProject = !chatId && projectName && messages.length === 0;

            const response = await fetch('/api/chat', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    messages: [...messages, userMessage],
                    image: userMessage.image,
                    projectName: isNewProject ? projectName : undefined
                }),
                signal: abortController.signal,
            });

            // If this was a new project, notify parent and refresh sidebar
            if (isNewProject) {
                // Dispatch event to refresh sidebar
                window.dispatchEvent(new CustomEvent('refreshConversations'));
                // Notify parent component about the created chat
                onChatCreated?.(crypto.randomUUID()); // This will be updated when we get the real ID
            }

            if (!response.ok) {
                throw new Error('Failed to send message');
            }

            if (!response.body) {
                throw new Error('No response body');
            }

            const reader = response.body.getReader();
            const decoder = new TextDecoder();
            const assistantMessage: Message = {
                id: crypto.randomUUID(),
                role: 'assistant',
                content: '',
            };

            setMessages((prev) => [...prev, assistantMessage]);

            while (true) {
                const { done, value } = await reader.read();
                if (done) break;

                const chunk = decoder.decode(value, { stream: true });

                assistantMessage.content += chunk;
                setMessages((prev) => {
                    const newMessages = [...prev];
                    newMessages[newMessages.length - 1] = { ...assistantMessage };
                    return newMessages;
                });
            }
        } catch (error) {
            console.error('Error sending message:', error);
            toast.error('Failed to send message. Please check the console for details.');
        } finally {
            setStatus('ready');
            abortControllerRef.current = null;
        }
    };

    return (
        <div className="flex flex-col h-full w-full">
            <div className="flex-1 overflow-y-auto p-6 space-y-4 custom-scrollbar">
                {status === 'loading' ? (
                    <div className="flex flex-col items-center justify-center h-full text-muted-foreground">
                        <Bot className="w-12 h-12 mb-2 animate-pulse" />
                        <p>Loading chat history...</p>
                    </div>
                ) : messages.length === 0 ? (
                    <div className="flex flex-col items-center justify-center h-full max-w-4xl mx-auto w-full">
                        {/* Welcome Message */}
                        <div className="text-center mb-12 animate-fade-in">
                            <div className="w-16 h-16 rounded-2xl bg-primary/10 flex items-center justify-center mx-auto mb-4">
                                <Bot className="w-8 h-8 text-primary" />
                            </div>
                            <h1 className="text-3xl font-bold text-foreground mb-2">
                                How can I orchestrate your workflow today?
                            </h1>
                            <p className="text-muted-foreground">
                                GOTI - Generative Orchestrator of Technological Innovation
                            </p>
                            <p className="text-sm text-muted-foreground mt-1">
                                Expert guidance on frameworks, tools, and best practices
                            </p>
                        </div>

                        {/* Quick Action Cards */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 w-full max-w-3xl">
                            <QuickActionCard
                                icon={RefreshCw}
                                title="Analyze React Update"
                                description="Explain the latest React updates and how they affect my project"
                                onClick={() => setInput("Explain the latest React updates and how they affect my project")}
                            />
                            <QuickActionCard
                                icon={Wrench}
                                title="Refactor Workflow"
                                description="Help me refactor this codebase for better performance"
                                onClick={() => setInput("Help me refactor this codebase for better performance")}
                            />
                            <QuickActionCard
                                icon={Lightbulb}
                                title="Explain Concept"
                                description="Break down Server Components vs Client Components"
                                onClick={() => setInput("Break down Server Components vs Client Components")}
                            />
                            <QuickActionCard
                                icon={Bug}
                                title="Debug Issue"
                                description="Help me debug this TypeScript type error"
                                onClick={() => setInput("Help me debug this TypeScript type error")}
                            />
                        </div>
                    </div>
                ) : (
                    <>
                        {messages.map((m) => (
                            <div
                                key={m.id}
                                className={cn(
                                    "flex w-full animate-fade-in",
                                    m.role === 'user' ? "justify-end" : "justify-start"
                                )}
                            >
                                <div
                                    className={cn(
                                        "flex items-start max-w-[80%] rounded-lg p-4",
                                        m.role === 'user'
                                            ? "bg-primary text-primary-foreground"
                                            : "glass text-foreground"
                                    )}
                                >
                                    <div className="mr-3 mt-1 flex-shrink-0">
                                        {m.role === 'user' ? <User size={18} /> : <Bot size={18} />}
                                    </div>
                                    <div className="flex-1 min-w-0 overflow-hidden">
                                        {m.image && (
                                            <div className="mb-2">
                                                <img src={m.image} alt="User upload" className="max-w-full rounded-lg border border-border/50" />
                                            </div>
                                        )}
                                        {m.role === 'user' ? (
                                            <div className="whitespace-pre-wrap text-sm">{m.content}</div>
                                        ) : (
                                            <MarkdownMessage content={m.content} />
                                        )}
                                    </div>
                                </div>
                            </div>
                        ))}
                    </>
                )}
                {status === 'streaming' && (
                    <div className="flex justify-start w-full">
                        <div className="glass text-foreground rounded-lg p-4 flex items-center">
                            <Bot size={18} className="mr-3 animate-spin" />
                            <span className="animate-pulse text-sm">Thinking...</span>
                        </div>
                    </div>
                )}
                {/* Upload Indicator */}
                {isUploading && (
                    <div className="flex justify-center w-full animate-fade-in">
                        <div className="bg-muted text-muted-foreground text-sm rounded-full px-4 py-2 flex items-center shadow-sm">
                            <Loader2 size={14} className="mr-2 animate-spin" />
                            Indexing document...
                        </div>
                    </div>
                )}
                <div ref={messagesEndRef} />
            </div>

            <form onSubmit={handleSubmit} className="p-6 border-t border-border bg-background">
                <div className="max-w-4xl mx-auto">
                    {selectedImage && (
                        <div className="mb-4 relative inline-block animate-fade-in">
                            <img src={selectedImage} alt="Selected" className="h-20 w-20 object-cover rounded-lg border border-border" />
                            <button
                                type="button"
                                onClick={() => setSelectedImage(null)}
                                className="absolute -top-2 -right-2 bg-destructive text-destructive-foreground rounded-full p-1 hover:bg-destructive/90 transition-colors"
                                title="Remove image"
                            >
                                <X size={12} />
                            </button>
                        </div>
                    )}
                    {selectedFile && (
                        <div className="mb-4 flex items-center gap-3 animate-fade-in">
                            <div className="flex items-center gap-2 bg-muted rounded-lg px-3 py-2 border border-border">
                                <FileText size={18} className="text-primary" />
                                <span className="text-sm font-medium truncate max-w-[200px]">{selectedFile.name}</span>
                                <button
                                    type="button"
                                    onClick={() => setSelectedFile(null)}
                                    className="ml-1 text-muted-foreground hover:text-foreground transition-colors"
                                    title="Remove file"
                                >
                                    <X size={14} />
                                </button>
                            </div>
                            <label className="flex items-center gap-2 text-sm text-muted-foreground cursor-pointer hover:text-foreground">
                                <input
                                    type="checkbox"
                                    checked={selectedFile.addToKB}
                                    onChange={(e) => setSelectedFile({ ...selectedFile, addToKB: e.target.checked })}
                                    className="w-4 h-4 rounded border-border text-primary focus:ring-primary"
                                />
                                Add to KB
                            </label>
                        </div>
                    )}
                    <div className="flex gap-3">
                        <button
                            type="button"
                            onClick={() => imageInputRef.current?.click()}
                            className={cn(
                                "p-3 transition-colors rounded-lg hover:bg-muted",
                                isUploading ? "opacity-50 cursor-not-allowed" : "text-muted-foreground hover:text-foreground"
                            )}
                            disabled={isUploading || isTranscribing}
                            title="Upload Image"
                        >
                            <ImageIcon size={20} />
                        </button>
                        <button
                            type="button"
                            onClick={() => fileInputRef.current?.click()}
                            className={cn(
                                "p-3 transition-colors rounded-lg hover:bg-muted",
                                isUploading ? "opacity-50 cursor-not-allowed" : "text-muted-foreground hover:text-foreground"
                            )}
                            disabled={isUploading || isTranscribing}
                            title="Upload Document (PDF, JSON, MD)"
                        >
                            <Paperclip size={20} />
                        </button>
                        <button
                            type="button"
                            onClick={isRecording ? stopRecording : startRecording}
                            className={cn(
                                "p-3 transition-colors rounded-lg hover:bg-muted",
                                isRecording ? "text-red-500 animate-pulse" : "text-muted-foreground hover:text-foreground",
                                (isTranscribing || isUploading) && "opacity-50 cursor-not-allowed"
                            )}
                            disabled={isTranscribing || isUploading}
                            title={isRecording ? "Stop recording" : "Start recording"}
                        >
                            <Mic size={20} />
                        </button>
                        <input
                            type="file"
                            ref={imageInputRef}
                            onChange={handleFileSelect}
                            accept="image/*"
                            className="hidden"
                        />
                        <input
                            type="file"
                            ref={fileInputRef}
                            onChange={handleFileSelect}
                            accept=".pdf,.json,.md,.txt"
                            className="hidden"
                        />
                        <input
                            className="flex-1 p-3 border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-primary bg-background text-foreground placeholder:text-muted-foreground"
                            value={isTranscribing ? "Transcribing..." : input}
                            onChange={(e) => setInput(e.target.value)}
                            onPaste={handlePaste}
                            placeholder="Type a message or paste an image/file..."
                            disabled={isTranscribing || isUploading}
                        />
                        <button
                            type="submit"
                            disabled={status === 'streaming' || (!input.trim() && !selectedImage) || isTranscribing || isUploading}
                            className="px-6 py-3 bg-primary text-primary-foreground rounded-lg hover:bg-primary/90 disabled:opacity-50 transition-all hover:scale-105 active:scale-95 disabled:hover:scale-100"
                        >
                            <Send size={20} />
                        </button>
                    </div>
                </div>
            </form>
        </div>
    );
}

import { useState, useEffect } from 'react';
import { Brain, Plus, ClockCounterClockwise, Eye, Gear, UserCircle, SignOut } from '@phosphor-icons/react';
import { Button } from './ui/button';
import { ScrollArea } from './ui/scroll-area';
import { Separator } from './ui/separator';
import { mockConversations } from '@/lib/mockData';
import { formatDistanceToNow } from 'date-fns';
import { supabase } from '@/lib/supabase';
import { User } from '@supabase/supabase-js';
import { toast } from 'sonner';

interface GotiSidebarProps {
  onNewChat: () => void;
  activeConversationId?: string;
  onSelectConversation: (id: string) => void;
}

export function GotiSidebar({ onNewChat, activeConversationId, onSelectConversation }: GotiSidebarProps) {
  const [user, setUser] = useState<User | null>(null);

  useEffect(() => {
    // Get current user
    supabase.auth.getUser().then(({ data: { user } }) => {
      setUser(user);
    });

    // Listen for auth changes
    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      setUser(session?.user ?? null);
    });

    return () => subscription.unsubscribe();
  }, []);

  const handleSignOut = async () => {
    try {
      await supabase.auth.signOut();
      toast.success('Signed out successfully');
    } catch (error) {
      toast.error('Error signing out');
    }
  };

  const groupConversationsByDate = () => {
    const today: typeof mockConversations = [];
    const yesterday: typeof mockConversations = [];
    const older: typeof mockConversations = [];

    const now = new Date();
    const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const yesterdayStart = new Date(todayStart);
    yesterdayStart.setDate(yesterdayStart.getDate() - 1);

    mockConversations.forEach((conv) => {
      if (conv.date >= todayStart) {
        today.push(conv);
      } else if (conv.date >= yesterdayStart) {
        yesterday.push(conv);
      } else {
        older.push(conv);
      }
    });

    return { today, yesterday, older };
  };

  const { today, yesterday, older } = groupConversationsByDate();

  const ConversationGroup = ({ title, conversations }: { title: string; conversations: typeof mockConversations }) => {
    if (conversations.length === 0) return null;

    return (
      <div className="mb-6">
        <h3 className="px-3 mb-2 text-xs font-semibold text-muted-foreground uppercase tracking-wider">
          {title}
        </h3>
        <div className="space-y-1">
          {conversations.map((conv) => (
            <button
              key={conv.id}
              onClick={() => onSelectConversation(conv.id)}
              className={`w-full px-3 py-2 text-left text-sm rounded-lg transition-all ${activeConversationId === conv.id
                ? 'bg-primary text-primary-foreground'
                : 'text-foreground hover:bg-secondary'
                }`}
            >
              <div className="truncate font-medium">{conv.title}</div>
              <div className={`text-xs mt-1 ${activeConversationId === conv.id ? 'text-primary-foreground/70' : 'text-muted-foreground'
                }`}>
                {formatDistanceToNow(conv.date, { addSuffix: true })}
              </div>
            </button>
          ))}
        </div>
      </div>
    );
  };

  return (
    <aside className="glass-strong w-64 h-screen flex flex-col">
      {/* Header */}
      <div className="p-6 flex items-center gap-3">
        <div className="w-10 h-10 rounded-lg bg-gradient-to-br from-primary to-accent flex items-center justify-center">
          <Brain size={24} weight="duotone" className="text-primary-foreground" />
        </div>
        <div>
          <h1 className="font-bold text-lg tracking-tight text-gradient">GOTI</h1>
          <p className="text-xs text-muted-foreground leading-tight">
            Generative Orchestrator of<br />Technological Innovation
          </p>
        </div>
      </div>

      <Separator className="bg-border/50" />

      {/* New Chat Button */}
      <div className="p-4">
        <Button
          onClick={onNewChat}
          className="w-full bg-primary hover:bg-primary/90 text-primary-foreground"
        >
          <Plus size={18} weight="bold" className="mr-2" />
          New Chat
        </Button>
      </div>

      {/* Navigation */}
      <nav className="px-4 space-y-1">
        <Button variant="ghost" className="w-full justify-start text-foreground">
          <ClockCounterClockwise size={18} weight="duotone" className="mr-2" />
          Library
        </Button>
        <Button variant="ghost" className="w-full justify-start text-foreground">
          <Eye size={18} weight="duotone" className="mr-2" />
          Tool Watch
        </Button>
      </nav>

      <Separator className="my-4 bg-border/50" />

      {/* Conversation History */}
      <ScrollArea className="flex-1 px-4 custom-scrollbar">
        <ConversationGroup title="Today" conversations={today} />
        <ConversationGroup title="Yesterday" conversations={yesterday} />
        <ConversationGroup title="Older" conversations={older} />
      </ScrollArea>

      {/* Footer */}
      <div className="p-4 border-t border-border/50">
        <div className="space-y-2">
          <div className="flex items-center gap-3 px-3 py-2 rounded-lg">
            <div className="w-8 h-8 rounded-full bg-gradient-to-br from-primary to-accent flex items-center justify-center">
              {user?.user_metadata?.avatar_url ? (
                <img
                  src={user.user_metadata.avatar_url}
                  alt="User avatar"
                  className="w-full h-full rounded-full object-cover"
                />
              ) : (
                <UserCircle size={20} weight="duotone" className="text-primary-foreground" />
              )}
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium truncate">
                {user?.user_metadata?.full_name || user?.email?.split('@')[0] || 'You'}
              </p>
              <p className="text-xs text-muted-foreground truncate">{user?.email}</p>
            </div>
          </div>
          <div className="flex gap-2">
            <Button
              variant="ghost"
              size="sm"
              className="flex-1 justify-start gap-2 text-muted-foreground hover:text-foreground"
            >
              <Gear size={16} weight="duotone" />
              Settings
            </Button>
            <Button
              onClick={handleSignOut}
              variant="ghost"
              size="sm"
              className="flex-1 justify-start gap-2 text-muted-foreground hover:text-destructive"
            >
              <SignOut size={16} weight="bold" />
              Sign Out
            </Button>
          </div>
        </div>
      </div>
    </aside>
  );
}

