import * as React from "react"

import type {
    ToastActionElement,
    ToastProps,
} from "@/app/components/lovable/ui/toast"

const TOAST_LIMIT = 1
const TOAST_REMOVE_DELAY = 1000000

type ToasterToast = ToastProps & {
    id: string
    title?: React.ReactNode
    description?: React.ReactNode
    action?: ToastActionElement
}

const actionTypes = {
    ADD_TOAST: "ADD_TOAST",
    UPDATE_TOAST: "UPDATE_TOAST",
    DISMISS_TOAST: "DISMISS_TOAST",
    REMOVE_TOAST: "REMOVE_TOAST",
} as const

let count = 0

function genId() {
    count = (count + 1) % Number.MAX_SAFE_INTEGER
    return count.toString()
}

type ActionType = typeof actionTypes

type Action =
    | {
        type: ActionType["ADD_TOAST"]
        toast: ToasterToast
    }
    | {
        type: ActionType["UPDATE_TOAST"]
        toast: Partial<ToasterToast>
    }
    | {
        type: ActionType["DISMISS_TOAST"]
        toastId?: ToasterToast["id"]
    }
    | {
        type: ActionType["REMOVE_TOAST"]
        toastId?: ToasterToast["id"]
    }

interface State {
    toasts: ToasterToast[]
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>()

const addToRemoveQueue = (toastId: string) => {
    if (toastTimeouts.has(toastId)) {
        return
    }

    const timeout = setTimeout(() => {
        toastTimeouts.delete(toastId)
        dispatch({
            type: "REMOVE_TOAST",
            toastId: toastId,
        })
    }, TOAST_REMOVE_DELAY)

    toastTimeouts.set(toastId, timeout)
}

export const reducer = (state: State, action: Action): State => {
    switch (action.type) {
        case "ADD_TOAST":
            return {
                ...state,
                toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
            }

        case "UPDATE_TOAST":
            return {
                ...state,
                toasts: state.toasts.map((t) =>
                    t.id === action.toast.id ? { ...t, ...action.toast } : t
                ),
            }

        case "DISMISS_TOAST": {
            const { toastId } = action

            // ! Side effects ! - This could be extracted into a dismissToast() action,
            // but I'll keep it here for simplicity
            if (toastId) {
                addToRemoveQueue(toastId)
            } else {
                state.toasts.forEach((toast) => {
                    addToRemoveQueue(toast.id)
                })
            }

            return {
                ...state,
                toasts: state.toasts.map((t) =>
                    t.id === toastId || toastId === undefined
                        ? {
                            ...t,
                            open: false,
                        }
                        : t
                ),
            }
        }
        case "REMOVE_TOAST":
            if (action.toastId === undefined) {
                return {
                    ...state,
                    toasts: [],
                }
            }
            return {
                ...state,
                toasts: state.toasts.filter((t) => t.id !== action.toastId),
            }
    }
}

const listeners: Array<(state: State) => void> = []

let memoryState: State = { toasts: [] }

function dispatch(action: Action) {
    memoryState = reducer(memoryState, action)
    listeners.forEach((listener) => {
        listener(memoryState)
    })
}

type Toast = Omit<ToasterToast, "id">

function toast({ ...props }: Toast) {
    const id = genId()

    const update = (props: ToasterToast) =>
        dispatch({
            type: "UPDATE_TOAST",
            toast: { ...props, id },
        })
    const dismiss = () =>
        dispatch({
            type: "DISMISS_TOAST",
            toastId: id,
        })

    dispatch({
        type: "ADD_TOAST",
        toast: {
            ...props,
            id,
            open: true,
            onOpenChange: (open) => {
                if (!open) dismiss()
            },
        },
    })

    return {
        id,
        dismiss,
        update,
    }
}

function useToast() {
    const [state, setState] = React.useState<State>(memoryState)

    React.useEffect(() => {
        listeners.push(setState)
        return () => {
            const index = listeners.indexOf(setState)
            if (index > -1) {
                listeners.splice(index, 1)
            }
        }
    }, [state])

    return {
        ...state,
        toast,
        dismiss: (toastId?: string) => dispatch({ type: "DISMISS_TOAST", toastId }),
    }
}

export { useToast, toast }

import { RecursiveCharacterTextSplitter } from '@langchain/textsplitters';

/**
 * Split text into chunks for embedding
 * Uses recursive character splitting to maintain context
 */
export async function chunkText(
    text: string,
    chunkSize: number = 1000,
    chunkOverlap: number = 200
): Promise<string[]> {
    const splitter = new RecursiveCharacterTextSplitter({
        chunkSize,
        chunkOverlap,
        separators: ['\n\n', '\n', '. ', ' ', ''],
    });

    const chunks = await splitter.splitText(text);
    return chunks;
}

/**
 * Extract metadata from document content
 */
export function extractMetadata(content: string, source: string): Record<string, any> {
    return {
        source,
        length: content.length,
        wordCount: content.split(/\s+/).length,
        processedAt: new Date().toISOString(),
    };
}

/**
 * Process a document: extract text, chunk it, and prepare metadata
 */
export async function processDocument(
    title: string,
    content: string,
    source: string
): Promise<{
    title: string;
    content: string;
    source: string;
    chunks: string[];
    metadata: Record<string, any>;
}> {
    const chunks = await chunkText(content);
    const metadata = extractMetadata(content, source);

    return {
        title,
        content,
        source,
        chunks,
        metadata,
    };
}

/**
 * Validation utilities for API requests
 */

export interface ValidationResult {
    valid: boolean;
    error?: string;
}

/**
 * Validate chat request payload
 */
export function validateChatRequest(body: any): ValidationResult {
    if (!body.messages || !Array.isArray(body.messages)) {
        return { valid: false, error: 'Messages must be an array' };
    }

    if (body.messages.length === 0) {
        return { valid: false, error: 'Messages array cannot be empty' };
    }

    if (body.messages.length > 50) {
        return { valid: false, error: 'Too many messages (max 50)' };
    }

    for (const msg of body.messages) {
        if (!msg.role || !msg.content) {
            return { valid: false, error: 'Each message must have role and content' };
        }

        if (typeof msg.content !== 'string') {
            return { valid: false, error: 'Message content must be a string' };
        }

        if (msg.content.length > 50000) {
            return { valid: false, error: 'Message content too long (max 50000 chars)' };
        }

        if (!['user', 'assistant', 'system'].includes(msg.role)) {
            return { valid: false, error: 'Invalid message role' };
        }
    }

    return { valid: true };
}

/**
 * Validate document upload payload
 */
export function validateDocumentUpload(body: any): ValidationResult {
    if (!body.title || !body.content || !body.source) {
        return { valid: false, error: 'Missing required fields: title, content, source' };
    }

    if (typeof body.title !== 'string' || typeof body.content !== 'string' || typeof body.source !== 'string') {
        return { valid: false, error: 'Title, content, and source must be strings' };
    }

    if (body.title.length > 500) {
        return { valid: false, error: 'Title too long (max 500 chars)' };
    }

    if (body.content.length > 1000000) {
        return { valid: false, error: 'Document too large (max 1MB)' };
    }

    if (body.source.length > 200) {
        return { valid: false, error: 'Source name too long (max 200 chars)' };
    }

    return { valid: true };
}

/**
 * Validate document update payload
 */
export function validateDocumentUpdate(body: any): ValidationResult {
    if (!body.id) {
        return { valid: false, error: 'Document ID is required' };
    }

    if (typeof body.id !== 'string') {
        return { valid: false, error: 'Document ID must be a string' };
    }

    // Validate other fields if provided
    if (body.title !== undefined) {
        if (typeof body.title !== 'string' || body.title.length > 500) {
            return { valid: false, error: 'Invalid title' };
        }
    }

    if (body.content !== undefined) {
        if (typeof body.content !== 'string' || body.content.length > 1000000) {
            return { valid: false, error: 'Invalid content' };
        }
    }

    if (body.source !== undefined) {
        if (typeof body.source !== 'string' || body.source.length > 200) {
            return { valid: false, error: 'Invalid source' };
        }
    }

    return { valid: true };
}

/**
 * Sanitize string input to prevent injection attacks
 */
export function sanitizeString(input: string): string {
    // Remove any null bytes
    return input.replace(/\0/g, '');
}

