import { supabase } from './supabase';
import { generateEmbedding } from './embeddings';

/**
 * Perform vector similarity search in Supabase
 * Returns the most relevant document chunks based on the query
 */
export async function searchSimilarChunks(
    query: string,
    limit: number = 5,
    similarityThreshold: number = 0.7
): Promise<Array<{
    id: string;
    content: string;
    similarity: number;
    metadata: any;
    document_id: string;
}>> {
    // Generate embedding for the query
    const queryEmbedding = await generateEmbedding(query);

    // Perform similarity search using pgvector
    // Using cosine distance (1 - cosine_similarity)
    const { data, error } = await supabase.rpc('match_document_chunks', {
        query_embedding: queryEmbedding,
        match_threshold: 1 - similarityThreshold, // Convert similarity to distance
        match_count: limit,
    });

    if (error) {
        console.error('Error searching similar chunks:', error);
        throw error;
    }

    return data || [];
}

/**
 * Format retrieved chunks into context for the AI prompt
 */
export function formatContextForPrompt(
    chunks: Array<{
        content: string;
        metadata: any;
    }>
): string {
    if (chunks.length === 0) {
        return '';
    }

    const contextParts = chunks.map((chunk, index) => {
        const source = chunk.metadata?.source || 'Unknown source';
        return `[${index + 1}] From ${source}:\n${chunk.content}`;
    });

    return `\n\nRelevant context from knowledge base:\n${contextParts.join('\n\n---\n\n')}`;
}

const fs = require('fs');
const path = require('path');
const https = require('https');

async function testOpenAI() {
    try {
        // Read .env.local manually
        const envPath = path.join(__dirname, '.env.local');
        if (!fs.existsSync(envPath)) {
            console.error('Error: .env.local file not found.');
            return;
        }

        const envContent = fs.readFileSync(envPath, 'utf8');
        let apiKey = '';

        envContent.split('\n').forEach(line => {
            const parts = line.split('=');
            if (parts.length >= 2 && parts[0].trim() === 'OPENAI_API_KEY') {
                apiKey = parts.slice(1).join('=').trim();
            }
        });

        if (!apiKey) {
            console.error('Error: OPENAI_API_KEY not found in .env.local');
            return;
        }

        console.log('Testing OpenAI Key...');
        // console.log('Key being used:', apiKey.substring(0, 10) + '...' + apiKey.slice(-5));

        const options = {
            hostname: 'api.openai.com',
            path: '/v1/models',
            method: 'GET',
            headers: {
                'Authorization': `Bearer ${apiKey}`,
                'Content-Type': 'application/json'
            }
        };

        const req = https.request(options, (res) => {
            let data = '';

            res.on('data', (chunk) => {
                data += chunk;
            });

            res.on('end', () => {
                if (res.statusCode === 200) {
                    console.log('✅ OpenAI API Key is valid! Successfully connected to OpenAI.');
                } else {
                    console.error(`❌ OpenAI API connection failed. Status Code: ${res.statusCode}`);
                    try {
                        const errorBody = JSON.parse(data);
                        console.error('Error details:', errorBody.error ? errorBody.error.message : data);
                    } catch (e) {
                        console.error('Error body:', data);
                    }
                }
            });
        });

        req.on('error', (e) => {
            console.error('Request error:', e);
        });

        req.end();

    } catch (err) {
        console.error('Unexpected error:', err);
    }
}

